// Skip CSV re-parse if schedule already loaded in flow context
const schedule = flow.get('DEV16_schedule');
if (schedule && schedule.length > 0) {
    msg.payload = schedule;
    msg._cached = true;
    return [null, msg];
}
// First run or after Clear All: full CSV reload
msg._cached = false;
return [msg, null];

const now = new Date();
const riyadhTime = new Date(now.toLocaleString('en-US', { timeZone: 'Asia/Riyadh' }));
const dayNames = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
const currentDay  = dayNames[riyadhTime.getDay()];
const currentHour = riyadhTime.getHours();
const currentMin  = riyadhTime.getMinutes();
const timeStr = String(currentHour).padStart(2,'0') + ':' + String(currentMin).padStart(2,'0');

// 🔵 Show current checked day & time under the node for easy debugging
node.status({ fill: 'blue', shape: 'dot', text: `${currentDay} ${timeStr}` });

// Build lookup map once (cached in node context). Rebuild if _cached===false (fresh CSV load).
let schedMap = context.get('schedMap');
if (!schedMap || msg._cached === false) {
    const rows = Array.isArray(msg.payload) ? msg.payload : [msg.payload];
    schedMap = {};
    for (const row of rows) {
        if (!row.Enabled || row.Enabled === '0') continue;
        const tParts = String(row.Time).split(':');
        if (tParts.length === 2) {
            const paddedTime = tParts[0].padStart(2, '0') + ':' + tParts[1].padStart(2, '0');
            const k = row.Day.toLowerCase() + '_' + paddedTime + '_' + row.Command.toLowerCase();
            schedMap[k] = true;
        }
    }
    context.set('schedMap', schedMap);
    context.set('lastRun', {});
}

// SAFETY GUARD check: If schedule data exists, system is ready!
if (schedMap && Object.keys(schedMap).length > 0) {
    if (!flow.get('DEV16_ready')) {
        flow.set('DEV16_ready', true);
        const deferred = flow.get('DEV16_deferredGuardianMsg');
        if (deferred) {
            flow.set('DEV16_deferredGuardianMsg', null);
            node.warn('[DEV16] Schedule loaded from cache. Replaying deferred Guardian event.');
            node.send([null]);
        }
    }
}

const lastRun = context.get('lastRun') || {};

// O(1) lookup — only checks 2 keys instead of looping 168 rows
for (const cmd of ['on', 'off']) {
    const key = currentDay + '_' + timeStr + '_' + cmd;
    if (schedMap[key] && !lastRun[key]) {
        lastRun[key] = true;
        context.set('lastRun', lastRun);
        msg.payload       = cmd;
        msg.route         = (cmd === 'off') ? 'open'  : 'close';
        msg.expectedState = (cmd === 'off') ? 'on'    : 'off';
        msg.commandLabel  = (cmd === 'off') ? 'OFF (Open Breaker)' : 'ON (Close Breaker)';
        msg.source        = 'SCHEDULER';
        flow.set('DEV16_expectedState', msg.expectedState);
        flow.set('DEV16_expectedLabel', msg.commandLabel);
        return msg;
    }
}

// Cleanup stale lastRun entries (only keep within ±2 min window)
const curTotal = currentHour * 60 + currentMin;
const keys = Object.keys(lastRun);
for (let i = 0; i < keys.length; i++) {
    const k = keys[i];
    const parts = k.split('_');
    if (parts[0] !== currentDay) { delete lastRun[k]; continue; }
    const tp = parts[1] ? parts[1].split(':') : [0, 0];
    const kTotal = parseInt(tp[0], 10) * 60 + parseInt(tp[1], 10);
    if (Math.abs(kTotal - curTotal) > 2) delete lastRun[k];
}
context.set('lastRun', lastRun);
return null;

const now = new Date().toLocaleString('en-GB', { timeZone: 'Asia/Riyadh', hour12: false });
const label = msg.commandLabel || msg.route;
const src = msg.source || 'SCHEDULER';

// Set pending command so Verify State can confirm it
flow.set('DEV16_pendingCommand', {
  expectedState: msg.expectedState,
  commandLabel: label,
  retryCount: 0,
  sentAt: Date.now(),
  source: src
});

const log = flow.get('DEV16_log') || [];
const entry = `[${now}] [DEV16] ⏳ CMD SENT [${src}] → ${label} | Awaiting confirmation...`;
log.push(entry);
if (log.length > 100) log.shift();
flow.set('DEV16_log', log);
node.warn(entry);
return null;

const pending = flow.get('DEV16_pendingCommand');
if(!pending) return null;
return msg;

const pending = flow.get('DEV16_pendingCommand');
if (!pending) return null;

const now = new Date().toLocaleString('en-GB', { timeZone: 'Asia/Riyadh', hour12: false });
const log = flow.get('DEV16_log') || [];
const raw = String(msg.payload).toLowerCase().trim();
const isOpen = (raw === 'on' || raw === 'true' || raw === 'open');
const expectedOpen = (pending.expectedState === 'on');
const retries = pending.retryCount || 0;
const elapsed = Math.round((Date.now() - pending.sentAt) / 1000);

if (isOpen === expectedOpen) {
  const entry = `[${now}] [DEV16] ✅ CONFIRMED [${pending.source || 'SCHED'}] → ${pending.commandLabel} | Breaker: ${isOpen ? 'OPEN' : 'CLOSED'} | After ${elapsed}s`;
  log.push(entry);
  if (log.length > 100) log.shift();
  flow.set('DEV16_log', log);
  flow.set('DEV16_pendingCommand', null);
  flow.set('DEV16_alarmActive', false);
  flow.set('DEV16_guardianBusy', false);
  node.warn(entry);
  node.status({ fill: 'green', shape: 'dot', text: '✅ ' + pending.commandLabel });
  return [msg, null, null];

} else if (retries >= 3) {
  const entry = `[${now}] [DEV16] 🚨 ALARM → FAILED after 3 retries! Expected:${expectedOpen ? 'OPEN' : 'CLOSED'} Got:${isOpen ? 'OPEN' : 'CLOSED'} | ${pending.commandLabel} | HALTED`;
  log.push(entry);
  if (log.length > 100) log.shift();
  flow.set('DEV16_log', log);
  flow.set('DEV16_pendingCommand', null);
  flow.set('DEV16_alarmActive', true);
  flow.set('DEV16_guardianBusy', false);
  node.warn(entry);
  node.status({ fill: 'red', shape: 'ring', text: '🚨 ALARM FAILED!' });
  return [null, null, msg];

} else {
  pending.retryCount = retries + 1;
  flow.set('DEV16_pendingCommand', pending);
  const entry = `[${now}] [DEV16] ⚠️ RETRY #${pending.retryCount} [${pending.source || 'SCHED'}] → Expected:${expectedOpen ? 'OPEN' : 'CLOSED'} Got:${isOpen ? 'OPEN' : 'CLOSED'} | Retrying...`;
  log.push(entry);
  if (log.length > 100) log.shift();
  flow.set('DEV16_log', log);
  node.warn(entry);
  node.status({ fill: 'yellow', shape: 'ring', text: '⚠️ RETRY #' + pending.retryCount });
  msg.expectedState = pending.expectedState;
  msg.commandLabel  = pending.commandLabel;
  msg.route  = (pending.expectedState === 'on') ? 'open' : 'close';
  msg.source = pending.source || 'SCHED';
  return [null, msg, null];
}

const pending = flow.get('DEV16_pendingCommand');
if(!pending) return null;
msg.action = (pending.expectedState==='on') ? 'open' : 'close';
return msg;

const now = new Date().toLocaleString('en-GB', { timeZone: 'Asia/Riyadh', hour12: false });
const log = flow.get('DEV16_log') || [];
const entry = `[${now}] [DEV16] 🚨🚨 SYSTEM HALTED — Breaker did NOT respond after 3 retries. MANUAL CHECK REQUIRED!`;
log.push(entry);
if (log.length > 100) log.shift();
flow.set('DEV16_log', log);
node.warn(entry);
msg.payload = entry;
msg.topic = 'DEV16_ALARM';
return msg;

var riyadh = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Riyadh' }));
var timeStr = riyadh.toLocaleString('en-GB', { timeZone: 'Asia/Riyadh', hour12: false });
var log = flow.get('DEV16_log') || [];

function pushLog(line) {
    log.push(line);
    if (log.length > 100) log.shift();
    flow.set('DEV16_log', log);
}

var entityState = msg.data && msg.data.state;
if (entityState === 'unavailable' || entityState === 'unknown') {
    node.status({ fill: 'grey', shape: 'ring', text: 'NB2 unavailable' });
    return null;
}

var pending = flow.get('DEV16_pendingCommand');
if (pending) {
    return null;
}

var raw    = String(msg.payload).toLowerCase().trim();
var isOpen = (raw === 'on' || raw === 'true' || raw === 'open');

var schedule = flow.get('DEV16_schedule');
if (!schedule || !schedule.length) {
    node.status({ fill: 'grey', shape: 'ring', text: 'no schedule' });
    return null;
}

var dayNames   = ['sunday','monday','tuesday','wednesday','thursday','friday','saturday'];
var currentDay = dayNames[riyadh.getDay()];
var nowMinutes = riyadh.getHours() * 60 + riyadh.getMinutes();
var lastMinutes = -1;

for (var i = 0; i < schedule.length; i++) {
    var row = schedule[i];
    if (!row.Enabled || row.Enabled === '0' || row.Enabled === 0) continue;
    if (String(row.Day).toLowerCase() !== currentDay) continue;
    var parts  = String(row.Time).split(':');
    var rowMin = parseInt(parts[0], 10) * 60 + parseInt(parts[1], 10);
    if (rowMin <= nowMinutes && rowMin > lastMinutes) {
        lastMinutes = rowMin;
    }
}

if (lastMinutes === -1) {
    var yesterdayIndex = (riyadh.getDay() + 6) % 7;
    var yesterday = dayNames[yesterdayIndex];
    var yLastMin  = -1;
    for (var j = 0; j < schedule.length; j++) {
        var row2 = schedule[j];
        if (!row2.Enabled || row2.Enabled === '0' || row2.Enabled === 0) continue;
        if (String(row2.Day).toLowerCase() !== yesterday) continue;
        var parts2  = String(row2.Time).split(':');
        var rowMin2 = parseInt(parts2[0], 10) * 60 + parseInt(parts2[1], 10);
        if (rowMin2 > yLastMin) { yLastMin = rowMin2; }
    }
    if (yLastMin !== -1) {
        lastMinutes = yLastMin - 1440;
    }
}

var expectedHAState = 'on';
var expectedLabel = 'OFF (Open Breaker)';

if (lastMinutes !== -1) {
    // ⚙️ CONFIGURATION: Edit these values to adjust safety guard limits
    // DELAY_MINUTES: Must match your delay node timeout (e.g., 30 seconds = 0.5 minutes)
    var DELAY_MINUTES = 0.5;

    // SAFETY_THRESHOLD_MINUTES: Change this value to adjust the safety margin in minutes (default 5)
    var SAFETY_THRESHOLD_MINUTES = 5;

    var maxAllowedMinutes = lastMinutes + DELAY_MINUTES + SAFETY_THRESHOLD_MINUTES;

    if (nowMinutes >= lastMinutes && nowMinutes <= maxAllowedMinutes) {
        // Within active window: device is allowed to be ON or OFF
        expectedHAState = isOpen ? 'on' : 'off';
        expectedLabel = isOpen ? 'OFF (Open Breaker)' : 'ON (Close Breaker)';
    } else {
        // Outside allowed window: device MUST be OFF (breaker open / 'on' state)
        expectedHAState = 'on';
        expectedLabel = 'OFF (Open Breaker)';
    }
}

flow.set('DEV16_expectedState', expectedHAState);
flow.set('DEV16_expectedLabel', expectedLabel);

var expectedOpen = (expectedHAState === 'on');
var faultActive  = flow.get('DEV16_faultActive') || false;

if (isOpen === expectedOpen) {
    flow.set('DEV16_guardianMismatch', null);
    node.status({ fill: 'green', shape: 'dot', text: 'OK | ' + (expectedLabel || expectedHAState) });
    return null;
}

var e1 = '[' + timeStr + '] [DEV16] GUARDIAN MISMATCH - Actual:' +
    (isOpen ? 'OPEN' : 'CLOSED') + ' | Expected:' + (expectedOpen ? 'OPEN' : 'CLOSED');
pushLog(e1);
node.warn(e1);

if (expectedOpen && !isOpen) {
    flow.set('DEV16_guardianMismatch', null);
    if (faultActive) {
        var e2a = '[' + timeStr + '] [DEV16] GUARDIAN ALARM - Should be OFF + FAULT ACTIVE - MANUAL CHECK';
        pushLog(e2a); node.warn(e2a);
        node.status({ fill: 'red', shape: 'ring', text: 'FAULT+MISMATCH' });
        msg.payload = e2a; msg.topic = 'DEV16_GUARDIAN_ALARM';
        return [null, msg];
    }
    var e2b = '[' + timeStr + '] [DEV16] GUARDIAN ACTION - Should be OFF - Forcing OPEN now';
    pushLog(e2b); node.warn(e2b);
    node.status({ fill: 'red', shape: 'ring', text: 'Force OPEN' });
    msg.route = 'open'; msg.expectedState = 'on'; msg.commandLabel = 'OFF (Open Breaker)';
    msg.source = 'GUARDIAN'; msg.payload = 'open';
    flow.set('DEV16_guardianBusy', true);
    return [msg, null];
}

if (!expectedOpen && isOpen) {
    flow.set('DEV16_guardianMismatch', null);
    if (faultActive) {
        var e3a = '[' + timeStr + '] [DEV16] GUARDIAN ALARM - Should be ON + FAULT ACTIVE - Will NOT force close - MANUAL CHECK';
        pushLog(e3a); node.warn(e3a);
        node.status({ fill: 'orange', shape: 'ring', text: 'FAULT - no auto-close' });
        msg.payload = e3a; msg.topic = 'DEV16_GUARDIAN_ALARM';
        return [null, msg];
    }
    var e3b = '[' + timeStr + '] [DEV16] GUARDIAN ACTION - Should be ON - Waiting 30s then restore';
    pushLog(e3b); node.warn(e3b);
    node.status({ fill: 'yellow', shape: 'ring', text: 'Wait 30s then restore ON' });
    msg.route = 'close'; msg.expectedState = 'off'; msg.commandLabel = 'ON (Close Breaker)';
    msg.source = 'GUARDIAN'; msg.payload = 'close';
    flow.set('DEV16_guardianBusy', true);
    return [msg, null];
}

return null;

const log = flow.get('DEV16_log') || [];
if(!log.length){msg.payload='=== DEV16 LOG ===\nNo entries yet.';return msg;}
const confirmed = log.filter(l=>l.includes('✅ CONFIRMED')).length;
const retries   = log.filter(l=>l.includes('⚠️ RETRY')).length;
const alarms    = log.filter(l=>l.includes('🚨')).length;
const sent      = log.filter(l=>l.includes('⏳ CMD SENT')).length;
const guardian  = log.filter(l=>l.includes('GUARDIAN')).length;
const recovery  = log.filter(l=>l.includes('GUARDIAN') && (l.includes('Force')||l.includes('restore'))).length;

const header=[
  '═══════════════════════════════════════════════════',
  '           DEV16 — SMART GUARDIAN LOG REPORT      ',
  '═══════════════════════════════════════════════════',
  `  📤 Commands Sent       : ${sent}`,
  `  ✅ Confirmed OK        : ${confirmed}`,
  `  ⚠️ Retries             : ${retries}`,
  `  🚨 Alarms (FAILED)     : ${alarms}`,
  `  🐕 Guardian Checks     : ${guardian}`,
  `  ⚡ Auto-Recoveries     : ${recovery}`,
  `  🔴 Fault Active Now    : ${flow.get('DEV16_faultActive')?'YES':'no'}`,
  `  ⏳ Pending Command     : ${flow.get('DEV16_pendingCommand')?flow.get('DEV16_pendingCommand').commandLabel:'none'}`,
  `  🎯 Expected State      : ${flow.get('DEV16_expectedState')||'not set yet'}`,
  `  🟢 System Ready        : ${flow.get('DEV16_ready') ? 'YES' : 'NO (initializing)'}`,
  '═══════════════════════════════════════════════════',
  '  LAST 60 ENTRIES (newest first):',
  '───────────────────────────────────────────────────'
].join('\n');
msg.payload = header+'\n'+log.slice(-60).reverse().join('\n');
return msg;

flow.set('DEV16_log',[]);
flow.set('DEV16_pendingCommand',null);
flow.set('DEV16_alarmActive',false);
flow.set('DEV16_guardianBusy',false);
flow.set('DEV16_faultActive',false);
flow.set('DEV16_expectedState',null);
flow.set('DEV16_expectedLabel',null);
flow.set('DEV16_guardianMismatch',null);
flow.set('DEV16_schedule', null);      // Force full CSV reload on next tick
flow.set('DEV16_ready', false);        // Re-arm the startup guard
flow.set('DEV16_deferredGuardianMsg', null);
node.status({fill:'grey',shape:'ring',text:'Cleared'});
node.warn('[DEV16] All state cleared manually.');
return null;

msg.payload = 'off';
msg.route = 'open';
msg.expectedState = 'on';
msg.commandLabel = 'OFF (Open Breaker)';
msg.source = 'SCHEDULER';
flow.set('DEV16_expectedState', msg.expectedState);
flow.set('DEV16_expectedLabel', msg.commandLabel);
return msg;
